int open_msr(struct inode *inode, struct file *file) {
    int cpu = -1;
    int ret = 0;

    if (!inode || !file) {
        return -EINVAL;
    }

    if (!capable(CAP_SYS_RAWIO)) {
        return -EPERM;
    }

    cpu = get_cpu_from_path(file);
    if (cpu < 0) {
        return -ENXIO;
    }

    if (!cpu_online(cpu)) {
        return -ENXIO;
    }

    if (!msr_supported(cpu)) {
        return -EIO;
    }

    return ret;
}
